// Full-viewport background: the bunny reconstruction from the SFM project
// (public/cloud.json, generated by tools/make_cloud.py). Points fly in from
// noise and "triangulate"; camera frustums register one by one; scroll orbits
// the view and the mouse adds parallax.
import { Canvas, useFrame, useThree } from "@react-three/fiber";
import { useEffect, useMemo, useRef, useState } from "react";
import * as THREE from "three";
import { motion, prefersReducedMotion } from "./motion";

const pointsVert = /* glsl */ `
  uniform float uTime;
  uniform float uAssemble;
  uniform float uSize;
  uniform float uPixelRatio;
  attribute vec3 aStart;
  attribute float aSeed;
  varying float vAlpha;
  varying vec3 vColor;
  void main() {
    float t = clamp(uAssemble * 1.6 - aSeed * 0.6, 0.0, 1.0);
    t = 1.0 - pow(1.0 - t, 3.0);
    vec3 p = mix(aStart, position, t);
    p += 0.004 * vec3(sin(uTime * 1.3 + aSeed * 40.0), cos(uTime * 1.1 + aSeed * 30.0), sin(uTime * 0.9 + aSeed * 20.0));
    vec4 mv = modelViewMatrix * vec4(p, 1.0);
    gl_Position = projectionMatrix * mv;
    gl_PointSize = uSize * (0.7 + 0.6 * aSeed) * uPixelRatio / -mv.z;
    float h = clamp(position.y * 0.5 + 0.5, 0.0, 1.0);
    vColor = mix(vec3(0.46, 0.73, 0.0), vec3(0.13, 0.83, 0.93), h);
    vAlpha = (0.45 + 0.55 * aSeed) * (0.35 + 0.65 * t);
  }
`;
const pointsFrag = /* glsl */ `
  uniform float uOpacity;
  varying float vAlpha;
  varying vec3 vColor;
  void main() {
    float d = length(gl_PointCoord - 0.5);
    if (d > 0.5) discard;
    float a = smoothstep(0.5, 0.05, d);
    gl_FragColor = vec4(vColor, a * vAlpha * uOpacity);
  }
`;
const linesVert = /* glsl */ `
  uniform float uAssemble;
  attribute float aIdx;
  varying float vA;
  void main() {
    float start = 0.35 + aIdx * 0.55;
    vA = smoothstep(start, start + 0.08, uAssemble);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;
const linesFrag = /* glsl */ `
  uniform vec3 uColor;
  uniform float uOpacity;
  varying float vA;
  void main() { gl_FragColor = vec4(uColor, vA * uOpacity); }
`;

// Camera centres sit ~5.5 units out; pull them in so the rig frames the cloud.
const CAM_RING_SCALE = 0.36;
const FRUSTUM = { w: 0.05, h: 0.036, d: 0.09 };

function buildGeometry(data) {
  const n = data.n_points;
  const pos = new Float32Array(data.points);
  const start = new Float32Array(n * 3);
  const seed = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    const u = Math.random() * Math.PI * 2;
    const v = Math.acos(2 * Math.random() - 1);
    const r = 3 + Math.random() * 3;
    start[i * 3] = Math.sin(v) * Math.cos(u) * r;
    start[i * 3 + 1] = Math.sin(v) * Math.sin(u) * r;
    start[i * 3 + 2] = Math.cos(v) * r;
    seed[i] = Math.random();
  }
  const points = new THREE.BufferGeometry();
  points.setAttribute("position", new THREE.BufferAttribute(pos, 3));
  points.setAttribute("aStart", new THREE.BufferAttribute(start, 3));
  points.setAttribute("aSeed", new THREE.BufferAttribute(seed, 1));

  // Frustums: apex at camera centre, 4 image-plane corners along the camera axes
  // (rows of R are the camera x/y/z axes in world coordinates).
  const seg = [];
  const idx = [];
  const centres = [];
  const m = data.cameras.length;
  data.cameras.forEach((cam, k) => {
    const C = new THREE.Vector3(...cam.c).multiplyScalar(CAM_RING_SCALE);
    const [rx, ry, rz] = cam.R.map((row) => new THREE.Vector3(...row));
    const corner = (sx, sy) =>
      C.clone()
        .addScaledVector(rx, sx * FRUSTUM.w)
        .addScaledVector(ry, sy * FRUSTUM.h)
        .addScaledVector(rz, FRUSTUM.d);
    const c = [corner(-1, -1), corner(1, -1), corner(1, 1), corner(-1, 1)];
    const push = (a, b) => {
      seg.push(a.x, a.y, a.z, b.x, b.y, b.z);
      idx.push(k / m, k / m);
    };
    c.forEach((p) => push(C, p));
    for (let i = 0; i < 4; i++) push(c[i], c[(i + 1) % 4]);
    centres.push(C);
  });
  const frustums = new THREE.BufferGeometry();
  frustums.setAttribute("position", new THREE.Float32BufferAttribute(seg, 3));
  frustums.setAttribute("aIdx", new THREE.Float32BufferAttribute(idx, 1));

  const path = new THREE.BufferGeometry().setFromPoints(centres.concat([centres[0]]));
  const pIdx = new Float32Array(centres.length + 1).map((_, i) => Math.min(i, m - 1) / m);
  path.setAttribute("aIdx", new THREE.BufferAttribute(pIdx, 1));
  return { points, frustums, path };
}

function Reconstruction({ data }) {
  const group = useRef();
  const { camera, gl, size } = useThree();
  const geo = useMemo(() => buildGeometry(data), [data]);
  const t0 = useRef(null);

  const pointsMat = useMemo(
    () =>
      new THREE.ShaderMaterial({
        vertexShader: pointsVert,
        fragmentShader: pointsFrag,
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        uniforms: {
          uTime: { value: 0 },
          uAssemble: { value: prefersReducedMotion ? 1 : 0 },
          uSize: { value: 26 },
          uPixelRatio: { value: gl.getPixelRatio() },
          uOpacity: { value: 1 },
        },
      }),
    [gl]
  );
  const lineMat = useMemo(
    () =>
      new THREE.ShaderMaterial({
        vertexShader: linesVert,
        fragmentShader: linesFrag,
        transparent: true,
        depthWrite: false,
        uniforms: {
          uAssemble: { value: prefersReducedMotion ? 1 : 0 },
          uColor: { value: new THREE.Color("#dfe7ef") },
          uOpacity: { value: 0.4 },
        },
      }),
    []
  );
  const pathMat = useMemo(
    () =>
      new THREE.ShaderMaterial({
        vertexShader: linesVert,
        fragmentShader: linesFrag,
        transparent: true,
        depthWrite: false,
        uniforms: {
          uAssemble: { value: prefersReducedMotion ? 1 : 0 },
          uColor: { value: new THREE.Color("#22D3EE") },
          uOpacity: { value: 0.25 },
        },
      }),
    []
  );

  const look = useRef(new THREE.Vector3());
  const smooth = useRef({ mx: 0, my: 0, scroll: 0, hero: 0 });

  useFrame((state, dt) => {
    const t = state.clock.elapsedTime;
    if (t0.current === null) t0.current = t;
    const assemble = prefersReducedMotion ? 1 : Math.min(1, (t - t0.current) / 3.2);
    pointsMat.uniforms.uTime.value = t;
    pointsMat.uniforms.uAssemble.value = assemble;
    lineMat.uniforms.uAssemble.value = assemble;
    pathMat.uniforms.uAssemble.value = assemble;

    const s = smooth.current;
    const k = 1 - Math.exp(-dt * 4);
    s.mx += (motion.mouseX - s.mx) * k;
    s.my += (motion.mouseY - s.my) * k;
    s.scroll += (motion.scroll - s.scroll) * k;
    s.hero += (motion.heroScroll - s.hero) * k;

    const idle = prefersReducedMotion ? 0 : t * 0.05;
    const az = 0.6 + idle + s.scroll * Math.PI * 1.5 + s.mx * 0.25;
    const el = 0.18 - s.my * 0.12 + Math.sin(s.scroll * Math.PI) * 0.25;
    const r = THREE.MathUtils.lerp(4.2, 3.0, Math.sin(s.scroll * Math.PI));
    camera.position.set(Math.sin(az) * Math.cos(el) * r, Math.sin(el) * r, Math.cos(az) * Math.cos(el) * r);

    // In the hero, push the cloud to the right half on wide screens.
    const wide = size.width / size.height > 1.15;
    const shift = wide ? (1 - s.hero) * 1.3 : 0;
    const right = new THREE.Vector3().subVectors(camera.position, look.current).cross(camera.up).normalize();
    look.current.set(0, wide ? 0 : 0.25 * (1 - s.hero), 0).addScaledVector(right, shift);
    camera.lookAt(look.current);

    // Dim behind content so text stays readable.
    const dim = THREE.MathUtils.lerp(1, 0.32, s.hero);
    pointsMat.uniforms.uOpacity.value = dim;
    lineMat.uniforms.uOpacity.value = 0.4 * dim * THREE.MathUtils.lerp(0.55, 1, s.hero);
    pathMat.uniforms.uOpacity.value = 0.25 * dim;
  });

  return (
    <group ref={group}>
      <points geometry={geo.points} material={pointsMat} />
      <lineSegments geometry={geo.frustums} material={lineMat} />
      <line geometry={geo.path} material={pathMat} />
    </group>
  );
}

export default function CloudScene({ onStats }) {
  const [data, setData] = useState(null);
  useEffect(() => {
    let alive = true;
    fetch("/cloud.json")
      .then((r) => r.json())
      .then((d) => {
        if (!alive) return;
        setData(d);
        onStats?.({ points: d.n_points, cameras: d.n_cameras });
      })
      .catch(() => {});
    return () => {
      alive = false;
    };
  }, [onStats]);

  return (
    <div className="fixed inset-0 z-0 pointer-events-none" aria-hidden="true">
      <Canvas
        dpr={[1, 1.75]}
        camera={{ fov: 38, near: 0.05, far: 50, position: [0, 0.5, 3.6] }}
        gl={{ antialias: true, alpha: true, powerPreference: "high-performance" }}
      >
        {data && <Reconstruction data={data} />}
      </Canvas>
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,transparent_40%,#05070B_95%)]" />
    </div>
  );
}
